<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import Chart from './Chart.vue'

type Item=Record<string,any>
const fragment=new URLSearchParams(location.hash.slice(1));const given=fragment.get('token')
if(given){sessionStorage.setItem('buspeeler-token',given);history.replaceState(null,'',location.pathname)}
const token=sessionStorage.getItem('buspeeler-token')||''
const page=ref('项目'),projects=ref<Item[]>([]),projectId=ref(''),workspace=ref<Item>({}),busy=ref(false),error=ref('')
const pages=['项目','数据','分析','验证','协议','设备与设置']
const sessionId=ref(''),referenceId=ref(''),candidateId=ref(''),message=ref(''),messages=ref<Item[]>([]),frames=ref<Item[]>([]),reference=ref<Item>(),devices=ref<Item>({})
const field=ref('driver_door'),threshold=ref(0),windowStart=ref(0),windowEnd=ref(60),frameOffset=ref(0)
const projectForm=reactive({name:'捷达 VA3 2023 手动挡',scope:{vehicle:'捷达 VA3',year:2023,transmission:'MT',bus:'车身 CAN / 接入点待确认',version:'待确认'}})
const editorOpen=ref(false),editId=ref<string|null>(null),form=reactive<Item>({})
const origins=ref(''),unknowns=ref(''),hexId=ref('390')
const manualReference=ref(''),templateResults=ref<Item[]>([])
const referenceOpen=ref(false),isEst=ref(true),referenceFile=ref<File>(),referenceMeta=reactive({source:'est_serial',origin:'est-unknown',unit:'',accuracy:0,time_uncertainty:0.2,clock_scale:1,clock_offset:0,description:'EST 周期快照，设备固件待确认'})
const annotation=reactive({supersedes:null as string|null,field:'driver_door',start:0,end:1,stage:'baseline',note:'',excluded:false})
const validationForm=reactive({session_id:'',reference_id:'',field:'driver_door',max_error:0,min_samples:20,range_min:0,range_max:1,observation:''})
const exportIds=ref<string[]>([])
const captureForm=reactive({backend:'zlg',profile:'',interface:'can0',index:0,channel:0,bitrate:500000,serial_port:'',baudrate:115200,bytesize:8,parity:'N',stopbits:1,est_origin:'est-unknown',configuration_confirmed:false})
const firmware=ref<Item>({files:[]})
const stateNames:Record<string,string>={candidate:'候选',reference_matched:'参考匹配',pending_validation:'待独立验证',validated:'已验证',published:'已发布',rejected:'未通过',invalidated:'已失效',running:'运行中',queued:'排队中',completed:'已完成',failed:'失败',interrupted:'已中断',stopping:'正在停止'}
const currentCandidate=computed(()=> (workspace.value.candidate||[]).find((c:Item)=>c.id===candidateId.value))
const currentSession=computed(()=> (workspace.value.session||[]).find((s:Item)=>s.id===sessionId.value))
const stats=computed(()=> (workspace.value.job||[]).find((j:Item)=>j.kind==='statistics'&&j.status==='completed'&&j.inputs.session_id===sessionId.value)?.result?.messages?.find((m:Item)=>m.key===message.value))
const chartSeries=ref<{name:string,data:[number,number|null][]}[]>([])
let timer:number

async function api(path:string,body?:unknown,method?:string){
 const options:RequestInit={method:method||(body?'POST':'GET'),headers:{Authorization:`Bearer ${token}`}}
 if(body instanceof FormData)options.body=body
 else if(body){options.headers={...options.headers,'Content-Type':'application/json'};options.body=JSON.stringify(body)}
 const response=await fetch('/api'+path,options)
 if(!response.ok){const result=await response.json().catch(()=>({detail:'请求失败'}));throw new Error(typeof result.detail==='string'?result.detail:JSON.stringify(result.detail))}
 return response.json()
}
async function action(work:()=>Promise<unknown>){busy.value=true;error.value='';try{await work()}catch(e){error.value=(e as Error).message;ElMessage.error(error.value)}finally{busy.value=false}}
function path(suffix:string){return `/projects/${projectId.value}${suffix}`}
async function refresh(){if(projectId.value)workspace.value=await api(path('/workspace'))}
async function chooseProject(){exportIds.value=[];templateResults.value=[];sessionId.value='';referenceId.value='';candidateId.value='';frames.value=[];messages.value=[];chartSeries.value=[];await refresh();const p=projects.value.find(p=>p.id===projectId.value);if(p)Object.assign(projectForm,{name:p.name,scope:{...p.scope}})}
async function createProject(){const p=await api('/projects',projectForm);projects.value=await api('/projects');projectId.value=p.id;await chooseProject()}
async function demo(){await api(path('/demo'),{});await refresh();sessionId.value=workspace.value.session[0].id;candidateId.value=workspace.value.candidate[0].id;page.value='分析';await loadSession();referenceId.value=workspace.value.reference[0].id;await loadReference()}
async function uploadCan(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;await action(async()=>{const form=new FormData();form.append('file',file);const s=await api(path('/can'),form);await refresh();sessionId.value=s.id;await loadSession()});input.value=''}
async function uploadDbc(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;await action(async()=>{const form=new FormData();form.append('file',file);const result=await api(path('/dbc'),form);await refresh();if(result.unsupported.length)ElMessage.warning(result.unsupported.join('；'))});input.value=''}
async function saveReference(){if(!referenceFile.value&&!isEst.value&&manualReference.value.trim()){const rows=manualReference.value.trim().split('\n').map(line=>{const [t,v,q,valid]=line.split(',');return JSON.stringify({timestamp:Number(t),field:field.value,value:v.trim()===''?null:Number(v),quality:q?.trim()||'valid',expected_valid:valid?.trim()==='false'?false:valid?.trim()==='true'?true:null})});referenceFile.value=new File([rows.join('\n')],'人工参考.jsonl',{type:'text/plain'})}if(!referenceFile.value)throw new Error('请选择参考文件或填写独立观察数据');referenceMeta.source=isEst.value?'est_serial':referenceMeta.source;const form=new FormData();form.append('file',referenceFile.value);form.append('session_id',sessionId.value);form.append('meta',JSON.stringify(referenceMeta));form.append('est',String(isEst.value));const r=await api(path('/reference'),form);referenceId.value=r.id;referenceOpen.value=false;await refresh();await loadReference()}
async function loadSession(){referenceId.value='';reference.value=undefined;frameOffset.value=0;messages.value=await api(path(`/sessions/${sessionId.value}/messages`));message.value=messages.value[0]?.key||'';windowStart.value=messages.value[0]?.start||0;windowEnd.value=messages.value[0]?.end||60;await loadFrames()}
async function loadFrames(){if(!sessionId.value)return;frames.value=await api(path(`/sessions/${sessionId.value}/frames?message=${encodeURIComponent(message.value)}&start=${windowStart.value}&end=${windowEnd.value}&offset=${frameOffset.value}&limit=500`));await draw()}
async function loadReference(){reference.value=referenceId.value?await api(path(`/references/${referenceId.value}`)):undefined;await draw()}
async function draw(){if(!sessionId.value)return;const query=new URLSearchParams({message:message.value,start:String(windowStart.value),end:String(windowEnd.value),field:field.value});if(candidateId.value)query.set('candidate',candidateId.value);if(referenceId.value)query.set('reference',referenceId.value);chartSeries.value=await api(path(`/sessions/${sessionId.value}/plot?${query}`))}
async function startJob(kind:string){await api(path('/jobs'),{kind,session_id:sessionId.value,candidate_id:candidateId.value||null,reference_id:referenceId.value||null,field:field.value,message:message.value,max_length:16,start:windowStart.value,end:windowEnd.value});await refresh()}
function openCandidate(record?:Item){editId.value=record?.id||null;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,record?structuredClone(record.definition):{name:'Signal',channel:'can0',can_id:0x390,extended:false,fd:false,message_length:8,layout:{start:16,length:1,endian:'little_endian',signed:false},factor:1,offset:0,unit:'',semantic:field.value,kind:'physical',mux:null,invalid_raw:[],postprocess:'none',origins:['manual'],source_sessions:sessionId.value?[sessionId.value]:[],evidence:'',unresolved:[],lag:0,freshness:0.5});hexId.value=form.can_id.toString(16).toUpperCase();origins.value=form.origins.join('\n');unknowns.value=form.unresolved.join('\n');editorOpen.value=true}
async function saveCandidate(){form.can_id=parseInt(hexId.value,16);form.origins=origins.value.split('\n').map(s=>s.trim()).filter(Boolean);form.unresolved=unknowns.value.split('\n').map(s=>s.trim()).filter(Boolean);const c=await api(path('/candidates'),{definition:form,supersedes:editId.value});candidateId.value=c.id;editorOpen.value=false;await refresh();await draw()}
async function match(){await api(path(`/candidates/${candidateId.value}/match`),{session_id:sessionId.value,reference_id:referenceId.value,field:field.value,max_error:threshold.value});await refresh()}
async function addAnnotation(){await api(path('/annotations'),{...annotation,session_id:sessionId.value});annotation.supersedes=null;await refresh();ElMessage.success('操作证据已保存')}
async function freezeValidation(){await api(path('/validation-plans'),{...validationForm,candidate_id:candidateId.value,coverage:['positive','negative','invalid','timeout']});await refresh()}
async function runValidation(id:string){await api(path(`/validation-plans/${id}/run`),{});await refresh()}
async function exportBundle(experimental:boolean){const result=await api(path('/exports'),{candidates:exportIds.value,experimental});await refresh();await download(result.id)}
async function download(id:string){const response=await fetch('/api'+path(`/exports/${id}`),{headers:{Authorization:`Bearer ${token}`}});if(!response.ok)throw new Error('下载失败');const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=`buspeeler-${id}.zip`;a.click();URL.revokeObjectURL(url)}
onMounted(()=>action(async()=>{projects.value=await api('/projects');devices.value=await api('/devices');firmware.value=await api('/firmware');projectId.value=projects.value[0]?.id||'';await refresh();timer=window.setInterval(()=>{if(projectId.value&&!busy.value)refresh().catch(()=>{})},2500)}))
onBeforeUnmount(()=>clearInterval(timer))
</script>

<template>
 <div class="shell">
  <aside><div class="brand">◈ BUSPEELER<small>CAN 信号分析工作台</small></div><nav aria-label="主导航"><button v-for="item in pages" :key="item" :class="{active:page===item}" @click="page=item">{{ item }}</button></nav><div class="aside-note">本地运行 · 默认只读<br>候选不等于已验证</div></aside>
  <main v-loading="busy"><header><div><span class="eyebrow">WORKSPACE / {{ page }}</span><h1>{{ page==='项目'?'从原始数据到可追溯协议':page }}</h1></div><el-select v-model="projectId" placeholder="选择项目" class="project-select" @change="action(chooseProject)"><el-option v-for="p in projects" :key="p.id" :label="p.name" :value="p.id"/></el-select></header>
   <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb"/>
   <el-alert v-if="!token" title="请使用 Buspeeler 启动入口打开页面，以获得本机访问凭据。" type="warning" :closable="false"/>
   <section v-if="page==='项目'" class="grid-two"><article class="card"><h2>新建车辆项目</h2><p class="muted">范围信息随候选和验证记录保存。未知内容请保留为待确认。</p><el-form label-position="top"><el-form-item label="项目名称"><el-input v-model="projectForm.name"/></el-form-item><div class="grid-two"><el-form-item label="车型"><el-input v-model="projectForm.scope.vehicle"/></el-form-item><el-form-item label="年款"><el-input-number v-model="projectForm.scope.year" :min="1980" :max="2100"/></el-form-item><el-form-item label="变速箱"><el-select v-model="projectForm.scope.transmission"><el-option label="手动挡" value="MT"/><el-option label="自动挡" value="AT"/></el-select></el-form-item><el-form-item label="车辆/模块版本"><el-input v-model="projectForm.scope.version"/></el-form-item></div><el-form-item label="总线与接入位置"><el-input v-model="projectForm.scope.bus"/></el-form-item><el-button type="primary" @click="action(createProject)">创建项目</el-button><el-button :disabled="!projectId" @click="action(async()=>{await api(`/projects/${projectId}`,projectForm,'PUT');projects=await api('/projects');await refresh();ElMessage.success('范围已更新；已有未发布候选需重新修订验证')})">更新当前项目范围</el-button></el-form></article><article class="card intro"><span class="badge">首版研究工作台</span><h2>先看数据，再确认含义。</h2><p>导入 CAN 记录与参考测量，将位变化、状态操作和拟合结果放在同一时间轴上。</p><ol><li>采集或导入原始数据</li><li>关联参考并发现候选</li><li>使用独立会话验证</li><li>导出协议与证据报告</li></ol><el-button :disabled="!projectId" @click="action(demo)">载入合成演示</el-button><p class="muted">演示数据会醒目标记，不能用于正式发布。</p></article></section>
   <el-empty v-else-if="!projectId&&page!=='设备与设置'" description="请先创建或选择项目"/>
   <template v-else-if="page==='数据'">
    <div class="toolbar"><label class="upload">导入 CAN 日志<input type="file" accept=".log,.jsonl,.txt" @change="uploadCan"/></label><el-button :disabled="!sessionId" @click="referenceOpen=true">导入参考数据</el-button><el-button @click="page='设备与设置'">开始实机采集</el-button></div><p class="muted">支持 candump -L 与 JSONL；单文件 64 MiB / 50 万帧。原文保存，解析错误不会被隐藏。</p>
    <article class="card"><h2>采集会话</h2><el-table :data="workspace.session||[]" @row-click="(row:Item)=>action(async()=>{sessionId=row.id;await loadSession()})"><el-table-column prop="name" label="会话"/><el-table-column prop="count" label="帧数" width="100"/><el-table-column label="状态" width="180"><template #default="{row}"><el-tag :type="row.demo?'warning':row.status==='ready'?'success':'danger'">{{ row.demo?'合成演示':row.status==='ready'?'可分析':'存在解析错误' }}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link @click.stop="action(async()=>{sessionId=row.id;await loadSession();page='分析'})">分析</el-button></template></el-table-column></el-table><p v-if="currentSession" class="muted">已选：{{currentSession.name}} · 原文件 SHA-256：{{currentSession.artifact.sha256}}</p><pre v-if="currentSession?.errors?.length">{{currentSession.errors}}</pre></article>
    <article class="card"><h2>引导操作与人工观察</h2><p class="muted">顺序：基线 → 单项操作 → 恢复 → 对照动作 → 重复。时间采用所选会话时间轴；记录实际观察，不能仅记录操作指令。</p><el-form label-position="top" class="grid-three"><el-form-item label="目标字段"><el-input v-model="annotation.field"/></el-form-item><el-form-item label="开始 / 秒"><el-input-number v-model="annotation.start" :min="0"/></el-form-item><el-form-item label="结束 / 秒"><el-input-number v-model="annotation.end" :min="0"/></el-form-item><el-form-item label="操作阶段"><el-select v-model="annotation.stage"><el-option v-for="(label,key) in {baseline:'基线',positive:'正例',negative:'反例',invalid:'失效',timeout:'超时',repeat:'复测'}" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="观察记录"><el-input v-model="annotation.note"/></el-form-item><el-form-item label="有效性"><el-checkbox v-model="annotation.excluded">此区间排除分析</el-checkbox></el-form-item></el-form><el-button :disabled="!sessionId" @click="action(addAnnotation)">保存操作证据</el-button><el-table :data="(workspace.annotation||[]).filter((a:Item)=>a.session_id===sessionId&&!a.superseded_by)"><el-table-column prop="field" label="字段"/><el-table-column prop="stage" label="阶段"/><el-table-column prop="start" label="开始"/><el-table-column prop="end" label="结束"/><el-table-column prop="note" label="观察"/><el-table-column label="修订"><template #default="{row}"><el-button link @click="Object.assign(annotation,{field:row.field,start:row.start,end:row.end,stage:row.stage,note:row.note,excluded:row.excluded,supersedes:row.id})">调整区间 / 排除</el-button></template></el-table-column></el-table></article>
   </template>
   <template v-else-if="page==='分析'">
    <div class="toolbar"><el-select v-model="sessionId" placeholder="选择会话" @change="action(loadSession)"><el-option v-for="s in workspace.session||[]" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-select v-model="referenceId" clearable placeholder="选择参考" @change="action(loadReference)"><el-option v-for="r in (workspace.reference||[]).filter((r:Item)=>r.session_id===sessionId)" :key="r.id" :label="r.name" :value="r.id"/></el-select><el-input v-model="field" placeholder="参考字段" style="width:150px" @change="action(draw)"/><el-button :disabled="!sessionId" @click="action(()=>startJob('statistics'))">统计特征</el-button></div>
    <el-alert v-if="currentSession?.demo" title="合成演示数据，不属于实车验证证据" type="warning" :closable="false" class="mb"/>
    <div class="analysis-layout"><article class="card message-list"><h2>报文</h2><button v-for="m in messages" :key="m.key" :class="{selected:message===m.key}" @click="action(async()=>{message=m.key;frameOffset=0;await loadFrames()})"><strong>0x{{m.key.split(':')[1]}}</strong><span>{{m.key.split(':')[0]}} · {{m.count}} 帧 · {{m.key.split(':')[3]==='1'?'FD':'CAN'}}</span></button><el-empty v-if="!messages.length" description="先选择会话" :image-size="60"/></article>
     <article class="card signal-view"><h2>信号与参考</h2><div class="toolbar"><el-input-number v-model="windowStart" :min="0" :precision="3" size="small"/><span>至</span><el-input-number v-model="windowEnd" :min="0" :precision="3" size="small"/><el-button size="small" @click="action(loadFrames)">查看区间</el-button></div><Chart :series="chartSeries"/><details v-if="reference?.changes?.length"><summary>EST 自动变化标签（观测区间）</summary><el-table :data="reference.changes.filter((r:Item)=>r.field===field).slice(0,100)" max-height="200"><el-table-column prop="start" label="区间起点"/><el-table-column prop="end" label="区间终点"/><el-table-column prop="from" label="变化前"/><el-table-column prop="to" label="变化后"/></el-table></details><div v-if="stats"><h3>位翻转率 · bit 0 为字节最低位</h3><div class="bits"><span v-for="(flip,index) in stats.flips" :key="index" :title="`bit ${index}: ${flip}`" :style="{background:`rgba(22,137,121,${0.08+Number(flip||0)*0.92})`}">{{index}}</span></div><p class="muted">周期 {{stats.period?.toFixed(4)}} 秒 · 抖动 {{stats.jitter?.toFixed(4)}} 秒 · 计数器候选 {{stats.counter_candidates.length}}</p></div><el-table :data="frames.slice(0,100)" height="250"><el-table-column label="时间 / 秒" width="130"><template #default="{row}">{{Number(row.timestamp).toFixed(6)}}</template></el-table-column><el-table-column prop="data" label="原始数据"/><el-table-column prop="time_source" label="时间来源" width="140"/></el-table><div class="toolbar"><el-button :disabled="frameOffset===0" @click="action(async()=>{frameOffset=Math.max(0,frameOffset-100);await loadFrames()})">上一页</el-button><el-button :disabled="frames.length<100" @click="action(async()=>{frameOffset+=100;await loadFrames()})">下一页</el-button><span class="muted">波形为窗口聚合，原始记录完整保存</span></div></article>
     <article class="card"><h2>候选与证据</h2><el-select v-model="candidateId" placeholder="选择候选" @change="action(draw)"><el-option v-for="c in workspace.candidate||[]" :key="c.id" :label="`${c.definition.name} · ${stateNames[c.state]}`" :value="c.id"/></el-select><div v-if="currentCandidate" class="candidate-summary"><el-tag>{{stateNames[currentCandidate.state]}}</el-tag><h3>{{currentCandidate.definition.name}}</h3><p>0x{{currentCandidate.definition.can_id.toString(16)}} · {{currentCandidate.definition.layout.start}} | {{currentCandidate.definition.layout.length}}</p><p>{{currentCandidate.definition.factor}} × raw + {{currentCandidate.definition.offset}} {{currentCandidate.definition.unit}}</p><p class="muted">{{currentCandidate.definition.evidence||'尚未填写证据'}}</p><ul><li v-for="u in currentCandidate.definition.unresolved" :key="u">{{u}}</li></ul><el-button @click="openCandidate(currentCandidate)">修订候选</el-button></div><el-button @click="openCandidate()">新建候选</el-button><hr/><el-button :disabled="!referenceId||!message" @click="action(()=>startJob('search'))">搜索位边界候选</el-button><el-button :disabled="!referenceId||!candidateId" @click="action(()=>startJob('fit'))">拟合比例与时间偏移</el-button><el-button :disabled="!message" @click="action(()=>startJob('isotp'))">普通寻址 ISO-TP 重组</el-button><el-form label-position="top"><el-form-item label="参考匹配最大误差"><el-input-number v-model="threshold" :min="0"/></el-form-item></el-form><el-button :disabled="!referenceId||!candidateId" @click="action(match)">检查参考匹配</el-button></article></div>
    <article class="card"><h2>分析任务与结果</h2><div v-for="job in workspace.job||[]" :key="job.id" class="job"><strong>{{job.kind}} · {{stateNames[job.status]}}</strong><p v-if="job.error" class="error">{{job.error}}</p><p v-if="job.result?.warning" class="muted">{{job.result.warning}}</p><div v-if="job.result?.best">factor {{job.result.best.factor}} · offset {{job.result.best.offset}} · 延迟 {{job.result.best.lag}} s · RMSE {{job.result.best.rmse}} <el-button size="small" @click="action(async()=>{const c=await api(path(`/jobs/${job.id}/adopt`),{});await refresh();candidateId=c.id;openCandidate(c)})">保存为候选修订</el-button></div><el-table v-if="job.result?.candidates" :data="job.result.candidates" max-height="300"><el-table-column prop="layout.start" label="起始位"/><el-table-column prop="layout.length" label="位宽"/><el-table-column label="字节序"><template #default="{row}">{{row.layout.endian==='little_endian'?'小端':'大端'}}</template></el-table-column><el-table-column prop="layout.signed" label="有符号"/><el-table-column prop="rmse" label="RMSE"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="action(async()=>{const c=await api(path(`/jobs/${job.id}/adopt?rank=${job.result.candidates.indexOf(row)}`),{});await refresh();candidateId=c.id;openCandidate(c)})">建立候选</el-button></template></el-table-column></el-table><details v-if="job.result"><summary>查看完整结果</summary><pre>{{JSON.stringify(job.result,null,2)}}</pre></details><el-button v-if="['failed','interrupted'].includes(job.status)" size="small" @click="action(async()=>{await api(path('/jobs'),job.inputs);await refresh()})">基于原始输入重跑</el-button></div></article>
   </template>
   <template v-else-if="page==='验证'">
    <el-alert title="与 EST 输出一致只是参考匹配；正式发布还需独立会话、独立参考和完整操作证据。" type="info" :closable="false" class="mb"/>
    <article class="card"><h2>冻结独立验证计划</h2><el-form label-position="top" class="grid-three"><el-form-item label="待验证候选"><el-select v-model="candidateId"><el-option v-for="c in workspace.candidate||[]" :key="c.id" :label="`${c.definition.name} · ${stateNames[c.state]}`" :value="c.id"/></el-select></el-form-item><el-form-item label="独立 CAN 会话"><el-select v-model="validationForm.session_id"><el-option v-for="s in workspace.session||[]" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="独立参考"><el-select v-model="validationForm.reference_id"><el-option v-for="r in (workspace.reference||[]).filter((r:Item)=>r.session_id===validationForm.session_id)" :key="r.id" :label="`${r.name} · ${r.meta.source}`" :value="r.id"/></el-select></el-form-item><el-form-item label="参考字段"><el-input v-model="validationForm.field"/></el-form-item><el-form-item label="最大允许误差"><el-input-number v-model="validationForm.max_error" :min="0"/></el-form-item><el-form-item label="最少样本数"><el-input-number v-model="validationForm.min_samples" :min="3"/></el-form-item><el-form-item label="验证范围下限"><el-input-number v-model="validationForm.range_min"/></el-form-item><el-form-item label="验证范围上限"><el-input-number v-model="validationForm.range_max"/></el-form-item><el-form-item label="独立性、精度与操作安排"><el-input v-model="validationForm.observation" type="textarea"/></el-form-item></el-form><p class="muted">在数据页记录正例、反例、失效与超时的实际时间区间。冻结后不能修改门槛；失败需创建候选修订重新验证。</p><el-button type="primary" @click="action(freezeValidation)">冻结计划</el-button></article>
    <article class="card"><h2>计划与报告</h2><div v-for="plan in workspace.validation_plan||[]" :key="plan.id" class="job"><span>计划 {{plan.id.slice(0,8)}} · 范围 {{plan.range_min}}–{{plan.range_max}} · 最大误差 {{plan.max_error}}</span><el-button @click="action(()=>runValidation(plan.id))">执行验证</el-button></div><div v-for="report in workspace.validation||[]" :key="report.id" class="job"><el-tag :type="report.passed?'success':'danger'">{{report.passed?'独立验证通过':'验证未通过'}}</el-tag><p>覆盖：{{report.coverage.join(' / ')||'尚无有效操作证据'}}</p><pre>{{JSON.stringify(report.result,null,2)}}</pre></div></article>
   </template>
   <template v-else-if="page==='协议'">
    <div class="toolbar"><label class="upload">导入已有 DBC<input type="file" accept=".dbc" @change="uploadDbc"/></label><el-button @click="action(async()=>{await api(path('/firmware-seeds'),{});await refresh()})">导入 VA3 固件候选</el-button><el-button :disabled="!sessionId" @click="action(async()=>{templateResults=await api(path(`/sessions/${sessionId}/template-match`))})">匹配当前会话</el-button><el-button :disabled="!exportIds.length" @click="action(()=>exportBundle(true))">导出实验包</el-button><el-button type="primary" :disabled="!exportIds.length" @click="action(()=>exportBundle(false))">正式发布</el-button></div>
    <article class="card"><h2>信号定义</h2><el-table :key="projectId" :data="workspace.candidate||[]" row-key="id" @selection-change="(rows:Item[])=>exportIds=rows.map(r=>r.id)"><el-table-column type="selection" :reserve-selection="true" width="50"/><el-table-column prop="definition.name" label="信号"/><el-table-column prop="definition.unit" label="单位" width="90"/><el-table-column label="状态"><template #default="{row}">{{stateNames[row.state]}}</template></el-table-column><el-table-column label="证据来源"><template #default="{row}">{{row.definition.origins.join('；')}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link @click="openCandidate(row)">修订</el-button></template></el-table-column></el-table><p class="muted">含整数截断或条件后处理的固件规则不能直接导出线性 DBC。内部模型保留完整规则。</p></article><article v-if="templateResults.length" class="card"><h2>模板匹配建议</h2><el-table :data="templateResults"><el-table-column prop="candidate" label="候选"/><el-table-column prop="valid_samples" label="可解码样本"/><el-table-column prop="range" label="观察范围"/><el-table-column prop="status" label="结论"/></el-table></article><article class="card"><h2>导出记录</h2><div v-for="pub in workspace.publication||[]" :key="pub.id" class="job"><el-tag :type="pub.experimental?'warning':'success'">{{pub.experimental?'实验包':'正式发布'}}</el-tag><span>往返验证 {{pub.manifest.roundtrip_checks}} 次</span><el-button link @click="action(()=>download(pub.id))">下载 DBC 与证据包</el-button></div></article><article class="card"><h2>固件目录 · {{firmware.files.length}} 个文件</h2><p class="muted">只读索引。VA3 2019 手动挡固件仅为 2023 款的候选来源；八条目标信号的局部静态规则不代表完整恢复。</p><el-table :data="firmware.files" height="260"><el-table-column prop="name" label="固件"/><el-table-column prop="bytes" label="字节" width="100"/><el-table-column prop="rt_formats" label="RT 格式字段数" width="160"/></el-table></article>
   </template>
   <template v-else-if="page==='设备与设置'">
    <article class="card"><h2>设备状态</h2><el-alert :title="devices.collector_available?'采集程序已就绪；硬件组合仍需验收':'采集程序尚未安装/构建'" :type="devices.collector_available?'info':'warning'" :closable="false"/><el-table :data="devices.backends||[]"><el-table-column prop="name" label="接口"/><el-table-column prop="model" label="型号"/><el-table-column prop="status" label="支持状态"/></el-table></article>
    <article class="card"><h2>同步采集</h2><el-form label-position="top" class="grid-three"><el-form-item label="接口"><el-select v-model="captureForm.backend"><el-option label="周立功" value="zlg"/><el-option label="创芯科技" value="chuangxin"/><el-option label="Linux SocketCAN" value="socketcan"/></el-select></el-form-item><el-form-item v-if="captureForm.backend!=='socketcan'" label="已验收设备配置"><el-select v-model="captureForm.profile"><el-option v-for="p in devices.profiles||[]" :key="p.profile" :label="p.model||p.profile" :value="p.profile"/></el-select></el-form-item><el-form-item v-else label="Linux 接口名称"><el-input v-model="captureForm.interface"/></el-form-item><el-form-item label="设备序号"><el-input-number v-model="captureForm.index" :min="0"/></el-form-item><el-form-item label="CAN 通道"><el-select v-model="captureForm.channel"><el-option label="双通道" :value="-1"/><el-option label="通道 1" :value="0"/><el-option label="通道 2" :value="1"/></el-select></el-form-item><el-form-item label="CAN 速率"><el-input-number v-model="captureForm.bitrate" :min="1000" :max="1000000"/></el-form-item><el-form-item label="EST 串口（可选）"><el-select v-model="captureForm.serial_port" clearable><el-option v-for="p in devices.serial||[]" :key="p.port" :label="`${p.port} ${p.description}`" :value="p.port"/></el-select></el-form-item><el-form-item label="串口波特率"><el-select v-model="captureForm.baudrate"><el-option v-for="n in [9600,38400,115200]" :key="n" :label="String(n)" :value="n"/></el-select></el-form-item><el-form-item label="数据位"><el-select v-model="captureForm.bytesize"><el-option :value="7"/><el-option :value="8"/></el-select></el-form-item><el-form-item label="校验位"><el-select v-model="captureForm.parity"><el-option v-for="v in ['N','E','O']" :key="v" :value="v"/></el-select></el-form-item><el-form-item label="停止位"><el-select v-model="captureForm.stopbits"><el-option :value="1"/><el-option :value="2"/></el-select></el-form-item><el-form-item label="EST 来源/实际固件身份"><el-input v-model="captureForm.est_origin"/></el-form-item></el-form><p class="muted">预填串口参数不是手册确认值。串口不发送 AT 指令，DTR/RTS 默认关闭；接入前核实电平与设备打开行为。</p><el-checkbox v-model="captureForm.configuration_confirmed">已核对接线、电平、串口参数和监听配置</el-checkbox><div class="toolbar"><el-button type="primary" :disabled="!projectId||!captureForm.configuration_confirmed" @click="action(async()=>{await api(path('/captures'),captureForm);await refresh()})">开始只读采集</el-button><el-button @click="action(async()=>{devices=await api('/devices')})">刷新设备</el-button></div><p class="muted">无厂商 SDK 的发行包仍可离线分析。SDK 不随包分发；技术人员按开发文档配置已核验的设备配置，页面才允许打开。</p></article>
    <article class="card"><h2>采集任务</h2><div v-for="c in workspace.capture||[]" :key="c.id" class="job"><strong>{{stateNames[c.status]||c.status}} · {{c.count}} 帧</strong><p class="error" v-if="c.error">{{c.error}}</p><p v-if="c.latest_frame" class="muted">最新帧：{{c.latest_frame.channel}} · 0x{{c.latest_frame.can_id.toString(16)}} · {{c.latest_frame.data}}</p><details v-if="c.latest_reference"><summary>EST 串口最新状态</summary><p class="muted">{{c.latest_reference.raw}}</p><el-table :data="c.latest_reference.fields" height="240"><el-table-column prop="field" label="字段"/><el-table-column prop="raw" label="原值"/><el-table-column prop="value" label="数值"/><el-table-column prop="unit" label="单位"/><el-table-column prop="quality" label="质量"/></el-table></details><el-button v-if="c.status==='running'" @click="action(async()=>{await api(path(`/captures/${c.id}/stop`),{});await refresh()})">停止并保存</el-button></div></article>
   </template>
  </main>
 </div>
 <el-dialog v-model="referenceOpen" title="导入参考数据" width="700px"><p>选择与当前 CAN 会话同步的 JSONL。EST 行格式含 timestamp、raw；独立参考含 timestamp、field、value、quality。</p><el-checkbox v-model="isEst">EST 原始串口行（39 字段）</el-checkbox><div v-if="!isEst"><el-form-item label="人工观察字段"><el-input v-model="field"/></el-form-item><el-form-item label="直接录入观察（时间,数值,质量,预期有效性；未知留空）"><el-input v-model="manualReference" type="textarea" :rows="5" placeholder="0,0,valid&#10;1,1,valid&#10;2,,unknown,false"/></el-form-item><p class="muted">也可选择仪器导出的文件；选择文件时优先使用文件内容。</p></div><el-form label-position="top" class="grid-two"><el-form-item label="参考文件"><input type="file" accept=".jsonl,.txt" @change="(e:Event)=>referenceFile=(e.target as HTMLInputElement).files?.[0]"/></el-form-item><el-form-item v-if="!isEst" label="参考类型"><el-select v-model="referenceMeta.source"><el-option label="独立仪器" value="instrument"/><el-option label="直接观察" value="observation"/></el-select></el-form-item><el-form-item label="来源组（同一设备/固件必须一致）"><el-input v-model="referenceMeta.origin"/></el-form-item><el-form-item label="单位"><el-input v-model="referenceMeta.unit"/></el-form-item><el-form-item label="测量误差上限"><el-input-number v-model="referenceMeta.accuracy" :min="0"/></el-form-item><el-form-item label="时间不确定度 / 秒"><el-input-number v-model="referenceMeta.time_uncertainty" :min="0" :step="0.1"/></el-form-item><el-form-item label="时钟比例"><el-input-number v-model="referenceMeta.clock_scale" :step="0.0001"/></el-form-item><el-form-item label="时钟偏移 / 秒"><el-input-number v-model="referenceMeta.clock_offset" :step="0.1"/></el-form-item><el-form-item label="设备、校准和来源说明"><el-input v-model="referenceMeta.description" type="textarea"/></el-form-item></el-form><template #footer><el-button type="primary" @click="action(saveReference)">保存参考</el-button></template></el-dialog>
 <el-dialog v-model="editorOpen" :title="editId?'创建候选修订（旧版本保留）':'新建候选'" width="850px"><el-form v-if="form.layout" label-position="top" class="grid-three"><el-form-item label="信号名称（英文标识）"><el-input v-model="form.name"/></el-form-item><el-form-item label="CAN ID（十六进制）"><el-input v-model="hexId"/></el-form-item><el-form-item label="通道"><el-input v-model="form.channel"/></el-form-item><el-form-item label="报文字节数"><el-input-number v-model="form.message_length" :min="1" :max="64"/></el-form-item><el-form-item label="帧类型"><el-checkbox v-model="form.extended">扩展 ID</el-checkbox><el-checkbox v-model="form.fd">CAN FD</el-checkbox></el-form-item><el-form-item label="字段类型"><el-select v-model="form.kind"><el-option label="物理信号" value="physical"/><el-option label="计数器候选" value="counter"/><el-option label="校验候选" value="checksum"/><el-option label="未知" value="unknown"/></el-select></el-form-item><el-form-item label="起始位"><el-input-number v-model="form.layout.start" :min="0" :max="511"/></el-form-item><el-form-item label="位宽"><el-input-number v-model="form.layout.length" :min="1" :max="64"/></el-form-item><el-form-item label="字节序"><el-select v-model="form.layout.endian"><el-option label="Intel 小端" value="little_endian"/><el-option label="Motorola 大端" value="big_endian"/></el-select><el-checkbox v-model="form.layout.signed">有符号</el-checkbox></el-form-item><el-form-item label="比例 factor"><el-input-number v-model="form.factor" :precision="8"/></el-form-item><el-form-item label="偏移 offset"><el-input-number v-model="form.offset" :precision="8"/></el-form-item><el-form-item label="单位"><el-input v-model="form.unit"/></el-form-item><el-form-item label="物理含义"><el-input v-model="form.semantic"/></el-form-item><el-form-item label="参考延迟 / 秒"><el-input-number v-model="form.lag" :step="0.05"/></el-form-item><el-form-item label="有效时间 / 秒"><el-input-number v-model="form.freshness" :min="0.001" :step="0.1"/></el-form-item><el-form-item label="后处理"><el-select v-model="form.postprocess"><el-option label="无" value="none"/><el-option label="向下取整" value="floor"/><el-option label="VA3 车速显示" value="va3_speed"/><el-option label="VA3 转向百分比" value="va3_steering"/><el-option label="VA3 转向灯多帧保持" value="va3_indicator_hold"/></el-select></el-form-item><el-form-item label="发现/标定会话"><el-select v-model="form.source_sessions" multiple><el-option v-for="s in workspace.session||[]" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="来源组（每行一个）"><el-input v-model="origins" type="textarea"/></el-form-item><el-form-item label="证据与规则说明"><el-input v-model="form.evidence" type="textarea"/></el-form-item><el-form-item label="尚未解决的问题（每行一个）"><el-input v-model="unknowns" type="textarea"/></el-form-item></el-form><details><summary>复用与无效码</summary><p>选择器变更需作为整个候选的新修订重新验证。</p><el-checkbox :model-value="!!form.mux" @change="(on:any)=>form.mux=on?{selector:{start:0,length:4,endian:'little_endian',signed:false},value:0}:null">使用单层复用条件</el-checkbox><div v-if="form.mux" class="grid-three"><el-form-item label="选择器起始位"><el-input-number v-model="form.mux.selector.start" :min="0"/></el-form-item><el-form-item label="选择器位宽"><el-input-number v-model="form.mux.selector.length" :min="1" :max="32"/></el-form-item><el-form-item label="分支值"><el-input-number v-model="form.mux.value" :min="0"/></el-form-item></div><el-form-item label="无效原始值（十进制逗号分隔）"><el-input :model-value="form.invalid_raw?.join(',')" @change="(s:string)=>form.invalid_raw=s.trim()?s.split(',').map(Number):[]"/></el-form-item></details><template #footer><el-button @click="editorOpen=false">取消</el-button><el-button type="primary" @click="action(saveCandidate)">保存候选</el-button></template></el-dialog>
</template>
